import React, { useEffect, useState } from 'react';
import ProductForm from './components/ProductForm';
import ProductList from './components/ProductList';
import Simulation from './components/Simulation';
import * as api from './api';

export default function App() {
  const [products, setProducts] = useState([]);
  const [editing, setEditing] = useState(null);
  const [defaults, setDefaults] = useState({ default_iof_percent: 5.38, default_dollar_rate: 5.0, freight_usd_per_kg: 22.5 });

  useEffect(()=>{
    load();
    api.getConfig().then(cfg => {
      setDefaults(cfg);
    });
  }, []);

  async function load() {
    const data = await api.fetchProducts();
    setProducts(data);
  }

  async function handleSave(payload) {
    if (editing) {
      await api.updateProduct(editing.id, payload);
      setEditing(null);
    } else {
      await api.createProduct(payload);
    }
    load();
  }

  async function handleDelete(id) {
    if (!window.confirm("Confirma exclusão do produto?")) return;
    await api.deleteProduct(id);
    load();
  }

  return (
    <div className="container">
      <div className="header">
        <h1>Gestão Acessórios Musicais</h1>
        <div className="small">MVP — Cálculos, listagem, simulação</div>
      </div>

      <div style={{display:'grid', gridTemplateColumns:'1fr 1fr', gap:12}}>
        <div>
          <ProductForm onSave={handleSave} product={editing} defaults={defaults} />
          <Simulation products={products} />
        </div>
        <div>
          <ProductList products={products} onEdit={(p)=>setEditing(p)} onDelete={handleDelete} />
        </div>
      </div>
    </div>
  );
}
